{
  "title": "agent.completions.message.InputAudio",
  "description": "Audio input for multimodal messages.",
  "type": "object",
  "properties": {
    "data": {
      "description": "Base64-encoded audio data.",
      "type": "string"
    },
    "format": {
      "description": "The audio format (e.g., \"wav\", \"mp3\").",
      "type": "string"
    }
  }
}

{
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  }
}

{
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "filename": {
      "description": "The filename for display purposes.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    }
  }
}

{
  "title": "functions.expression.StringInputSchema",
  "description": "Schema for a string input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the string.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "enum": {
      "description": "If provided, the string must be one of these values.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ]
    },
    "type": {
      "$ref": "functions.expression.StringInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.NumberInputSchema",
  "description": "Schema for a floating-point number input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the number.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "anyOf": [
        {
          "type": "number",
          "minimum": -3.4028234663852886e+38,
          "maximum": 3.4028234663852886e+38
        },
        {
          "type": "null"
        }
      ]
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "anyOf": [
        {
          "type": "number",
          "minimum": -3.4028234663852886e+38,
          "maximum": 3.4028234663852886e+38
        },
        {
          "type": "null"
        }
      ]
    },
    "type": {
      "$ref": "functions.expression.NumberInputSchemaType"
    }
  }
}
